import { Button } from '@refy-design/web';
import { Drawer } from '@refy-design/web';
import { FabMenu } from '@refy-design/web';
import { FileUpload } from '@refy-design/web';
import { Input } from '@refy-design/web';
import { useState } from 'react';
const stack = { display: 'grid', gap: 'var(--space-4)', minWidth: 0 } as const;
function FabMenuExample() {
  const [panel, setPanel] = useState(''),
    [query, setQuery] = useState(''),
    [name, setName] = useState(''),
    [materials, setMaterials] = useState(['Content guide', 'Visual references']);
  return (
    <div style={stack}>
      <FabMenu
        actions={[
          { id: 'create', label: 'New material' },
          { id: 'search', label: 'Search content' },
          { id: 'import', label: 'Import file' },
        ]}
        onSelect={setPanel}
      />
      <p>{materials.length} materials in the demo.</p>
      <Drawer
        open={Boolean(panel)}
        onOpenChange={(open) => {
          if (!open) setPanel('');
        }}
        title={
          panel === 'search'
            ? 'Search content'
            : panel === 'import'
              ? 'Import file'
              : 'New material'
        }
      >
        {panel === 'search' ? (
          <div style={stack}>
            <Input
              label="Search materials"
              value={query}
              onChange={(event) => setQuery(event.target.value)}
            />
            <ul>
              {materials
                .filter((item) => item.toLowerCase().includes(query.toLowerCase()))
                .map((item, i) => (
                  <li key={i}>{item}</li>
                ))}
            </ul>
          </div>
        ) : panel === 'import' ? (
          <FileUpload
            label="Add local file"
            onFilesChange={(files) => {
              setMaterials((items) => [...items, ...files.map((file) => file.name)]);
            }}
          />
        ) : (
          <form
            style={stack}
            onSubmit={(event) => {
              event.preventDefault();
              if (name.trim()) {
                setMaterials((items) => [...items, name.trim()]);
                setName('');
                setPanel('');
              }
            }}
          >
            <Input
              label="New material name"
              required
              value={name}
              onChange={(event) => setName(event.target.value)}
            />
            <Button type="submit" variant="primary">
              Create material
            </Button>
          </form>
        )}
      </Drawer>
    </div>
  );
}
export function Example() {
  return <FabMenuExample />;
}
